export const getConditionLifecycleActionsUrl = (encounterRef: string,
    params?: ConditionLifecycleActionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/encounters/${encodeURIComponent(String(encounterRef))}/condition-lifecycle-actions?${stringifiedParams}` : `/api/encounters/${encodeURIComponent(String(encounterRef))}/condition-lifecycle-actions`
}

