export const getPersistentDamageReviewUrl = (encounterRef: string,
    params?: PersistentDamageReviewParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/encounters/${encodeURIComponent(String(encounterRef))}/persistent-review?${stringifiedParams}` : `/api/encounters/${encodeURIComponent(String(encounterRef))}/persistent-review`
}

